def f(p):
    n = p['n']
    s = p['s']
    t = p['t']
    if s == t:
        return 0
    if s + t == 2 and s != 1:
        return 3 ** n - 1
    return (3 ** n - 1) // 2

def f(p):
    N = p['N']
    cnt = 0
    for s in range(1, N + 1):
        x = s
        seen = set()
        while x != 1 and x not in seen:
            seen.add(x)
            if x % 2 == 0:
                x = x // 2
            else:
                x = 3 * x - 1
        if x == 1:
            cnt += 1
    return cnt

def f(p):
    a = p['a']
    b = p['b']
    cnt = 0
    m = 1
    while 10800 * m <= 11 * b:
        if 10800 * m >= 11 * a:
            cnt += 1
        m += 2
    return cnt

def f(p):
    b = p['b']
    ops = p['ops']
    for i in range(len(ops)):
        x = ops[i]
        if x >= 0:
            b = b + x
        else:
            if b >= -x:
                b = b + x
            else:
                b = b - 15
        if b < 500:
            b = b - 10
        if (i + 1) % 3 == 0 and b >= 1000:
            b = b + b // 100
    return b
